// Port of test14.py.
//
//   parser = argparse.ArgumentParser()
//   parser.add_argument('--a', type=int, required=True)
//   parser.add_argument('--b', type=int, required=True)
//   parser.add_argument('--c', type=str, required=True)
//   args = parser.parse_args()
//   encoded_int1 = base58.b58encode_int(args.a)
//   encoded_int2 = base58.b58encode_int(args.b)
//   decoded_int  = base58.b58decode_int(args.c)
//   print(encoded_int1); print(encoded_int2); print(decoded_int)
//
// Both integers are encoded before the string is decoded, so a bad --c leaves
// stdout completely empty — nothing is printed until all three values exist.

import { basename } from 'node:path';

import { ArgumentParser, SystemExit, types } from './lib/argparse/index.mjs';
import * as base58 from './lib/base58/index.mjs';
import { PyError } from './lib/pyerrors.mjs';
import { pyPrint } from './lib/pyprint.mjs';
import { writeTraceback } from './lib/pytraceback.mjs';

// argparse defaults prog to basename(sys.argv[0]); the Node equivalent is the
// script path in argv[1].
const PROG = basename(process.argv[1] ?? 'test14.mjs');

// Mirrors the `decoded_int = ...` statement the reference traceback points at.
// The column span is the one baked into the compiled code object, covering
// `base58.b58decode_int(args.c)`.
const DECODE_CALL_SITE = { line: 12, colStart: 14, colEnd: 42 };

function main(argv) {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument(['--a'], { type: types.int, required: true });
  parser.addArgument(['--b'], { type: types.int, required: true });
  parser.addArgument(['--c'], { type: types.str, required: true });
  const args = parser.parseArgs(argv);

  const encodedInt1 = base58.b58encode_int(args.a); // 编码第一个整数
  const encodedInt2 = base58.b58encode_int(args.b); // 编码第二个整数
  const decodedInt = base58.b58decode_int(args.c); // 解码为整数

  pyPrint(encodedInt1);
  pyPrint(encodedInt2);
  pyPrint(decodedInt);
}

try {
  main(process.argv.slice(2));
} catch (error) {
  if (error instanceof SystemExit) {
    // argparse already wrote usage/help; returning normally lets Node drain
    // stdout and stderr before the status is applied.
    process.exitCode = error.code;
  } else if (error instanceof PyError) {
    writeTraceback(error, DECODE_CALL_SITE);
    process.exitCode = 1;
  } else {
    throw error;
  }
}
=== pyprint ===
// print() emulation. Python's print writes str(obj) followed by '\n' to
// stdout; for a bytes object str() is its repr, and for an int it is the plain
// decimal spelling.

import { PyBytes } from './pybytes.mjs';

/** Python's str() for the value kinds this program prints. */
export function pyStr(value) {
  if (value instanceof PyBytes) return value.toString();
  if (typeof value === 'bigint') return value.toString(10);
  return String(value);
}

/** print(value) — one value, default separator and newline, to stdout. */
export function pyPrint(value) {
  process.stdout.write(`${pyStr(value)}\n`);
}

