    pipe_head1) rp=$(timeout 10 /workspace/dataset/test14_executable --a 1 --b 1 --c A 2>/dev/null | head -1 >/dev/null; echo ${PIPESTATUS[0]}); jp=$(timeout 10 node /output/test14.mjs --a 1 --b 1 --c A 2>/dev/null | head -1 >/dev/null; echo ${PIPESTATUS[0]});;
